func NewBatchWithTime(batchOps []Op, t time.Time) OpBatch {
	ts := t.UTC()
	return OpBatch{
		Version:   1,
		Ops:       batchOps,
		CreatedAt: ts,
		BatchID:   NewBatchIDWithTime(ts),
	}
}

